class AssessmentSystem:
    FAIL_THRESHOLD = 60

    def __init__(self):
        self._students = {}

    @property
    def students(self):
        return self._students

    @students.setter
    def students(self, value):
        self._students = value

    def add_student(self, name, grade, major):
        self._students[name] = {'name': name, 'grade': grade, 'major': major, 'courses': {}}

    def add_course_score(self, name, course, score):
        if self._has_student(name):
            self._students[name]['courses'][course] = score

    def _has_student(self, name):
        return name in self._students

    def get_gpa(self, name):
        if not self._has_student(name) or not self._get_courses(name):
            return None
        return self._calculate_average(self._get_course_scores(name))

    def _get_courses(self, name):
        return self._students[name]['courses']

    def _get_course_scores(self, name):
        return list(self._get_courses(name).values())

    def _calculate_average(self, scores):
        if not scores:
            return None
        return sum(scores) / len(scores)

    def get_all_students_with_fail_course(self):
        return [name for name, student in self._students.items() if self._has_failing_course(student)]

    def _has_failing_course(self, student):
        return any(score < self.FAIL_THRESHOLD for score in student['courses'].values())

    def get_course_average(self, course):
        scores = self._get_scores_for_course(course)
        if not scores:
            return None
        return self._calculate_average(scores)

    def _get_scores_for_course(self, course):
        scores = []
        for student in self._students.values():
            if course in student['courses']:
                score = student['courses'][course]
                if score is not None:
                    scores.append(score)
        return scores

    def get_top_student(self):
        top_student = None
        top_gpa = 0
        for name in self._students:
            gpa = self.get_gpa(name)
            if self._is_better_gpa(gpa, top_gpa):
                top_gpa = gpa
                top_student = name
        return top_student

    def _is_better_gpa(self, gpa, current_top):
        return gpa is not None and gpa > current_top
